-- Línea base: esquema original de reportesbd.
-- Usa IF NOT EXISTS para que sea inocua si las tablas ya existen (base ya creada) y
-- para que también construya el esquema en una base de datos vacía.

CREATE TABLE IF NOT EXISTS "roles" (
  "id_perfil" INT PRIMARY KEY,
  "perfil" VARCHAR
);

CREATE TABLE IF NOT EXISTS "cargos" (
  "id_cargo" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cargo" VARCHAR,
  "estado" VARCHAR
);

CREATE TABLE IF NOT EXISTS "materiales" (
  "id_mat" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" INT,
  "nomMaterial" VARCHAR
);

CREATE TABLE IF NOT EXISTS "ecas" (
  "id_eca" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nomEca" VARCHAR,
  "direccion" VARCHAR,
  "comuna" VARCHAR,
  "estado" VARCHAR,
  "categoria" VARCHAR
);

CREATE TABLE IF NOT EXISTS "usuarios" (
  "id_user" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nomUser" VARCHAR,
  "apeUser" VARCHAR,
  "usuario" VARCHAR,
  "clave" VARCHAR,
  "cedula" INT,
  "id_perfil" INT,
  "id_cargo" INT,
  CONSTRAINT "usuarios_id_perfil_fkey" FOREIGN KEY ("id_perfil") REFERENCES "roles" ("id_perfil") DEFERRABLE,
  CONSTRAINT "usuarios_id_cargo_fkey" FOREIGN KEY ("id_cargo") REFERENCES "cargos" ("id_cargo") DEFERRABLE
);

CREATE TABLE IF NOT EXISTS "matReportado" (
  "id_mat" INT,
  "consecutivo" INT,
  "cantidad" FLOAT,
  "valor" INT,
  "id_user" INT,
  "id_eca" INT,
  "FechaRegistro" DATE,
  "FechaVenta" DATE,
  CONSTRAINT "matReportado_id_mat_fkey" FOREIGN KEY ("id_mat") REFERENCES "materiales" ("id_mat") DEFERRABLE,
  CONSTRAINT "matReportado_id_user_fkey" FOREIGN KEY ("id_user") REFERENCES "usuarios" ("id_user") DEFERRABLE,
  CONSTRAINT "matReportado_id_eca_fkey" FOREIGN KEY ("id_eca") REFERENCES "ecas" ("id_eca") DEFERRABLE
);
